const steps=["Decision","What Matters","Trade-offs","Incentives","Compounding","Chain Effects","Inversion","Stress Test","Judgment Check","Reversibility","Decision Drivers","Decision Overview"];
const $=s=>document.querySelector(s);
const esc=s=>String(s??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]));
const uid=()=>Math.random().toString(36).slice(2,9);
const judgmentCore=[
{id:"fresh",question:"If none of these options were your current or default path, and you were choosing fresh today, would the way you see this decision change?",summary:"Choosing fresh, with no current or default path"},
{id:"past",question:"If the time, money, effort or reputation you have already invested could not be recovered regardless of what you choose, would the way you see this decision change?",summary:"Removing past investment"},
{id:"framing",question:"If you described the options only by where each path could leave you, rather than as staying, leaving, gaining, losing, keeping or giving something up, would the way you see this decision change?",summary:"Describing the paths only by where they lead"},
{id:"vivid",question:"If the most recent, vivid or emotionally memorable example disappeared from your mind, would the way you see this decision change?",summary:"Removing the most recent, vivid or memorable example"}
];
const judgmentConditional=[
{id:"seen",question:"If nobody could know, judge, praise or be impressed by your choice, would the way you see this decision change?",summary:"Removing other people's awareness, judgment or praise"},
{id:"social",question:"If you did not know what the people around you or people you respect preferred, would the way you see this decision change?",summary:"Removing other people's stated preferences"},
{id:"uncertainty",question:"If making a choice today gave you no immediate relief from uncertainty, would the way you see this decision change?",summary:"Removing the immediate relief of ending uncertainty"}
];
const lifeDomains=[
{id:"purpose",title:"Purpose, values & identity",desc:"Your sense of purpose, beliefs, principles, character, spirituality, and who you want to be."},
{id:"health",title:"Physical & mental health",desc:"Your physical health, emotional wellbeing, energy, rest, and capacity to function well."},
{id:"partner",title:"Partner & intimate relationship",desc:"Your romantic relationship, marriage, intimacy, commitment, and shared future with a partner."},
{id:"family",title:"Family & caregiving",desc:"Your relationships with parents, children, relatives, and responsibilities to care for others."},
{id:"community",title:"Friends, community & belonging",desc:"Your friendships, social support, sense of belonging, community, and connection with others."},
{id:"work",title:"Work, career & contribution",desc:"Your work, business, career direction, professional growth, achievement, and contribution through what you do."},
{id:"learning",title:"Learning, growth & mastery",desc:"Your education, skills, intellectual development, personal growth, and becoming more capable over time."},
{id:"financial",title:"Financial & material life",desc:"Your income, savings, wealth, financial security, housing, and material standard of living."},
{id:"lifestyle",title:"Time, lifestyle & freedom",desc:"Your time, daily rhythm, flexibility, leisure, independence, and freedom over how you live."},
{id:"place",title:"Place, safety & stability",desc:"Where you live, your ability to stay or move, personal safety, living environment, and stability of your surroundings."}
];
const incentivePromises=[
{id:"financial",title:"Financial or material gain",desc:"More income, assets, resources or material benefit."},
{id:"security",title:"Security & stability",desc:"More predictability, safety or certainty."},
{id:"freedom",title:"Freedom & control",desc:"More autonomy over what you do or how you live."},
{id:"growth",title:"Growth & mastery",desc:"Becoming more capable, skilled or accomplished."},
{id:"belonging",title:"Belonging & connection",desc:"Feeling connected, included or closer to others."},
{id:"recognition",title:"Recognition & status",desc:"Respect, approval, prestige or being seen positively."},
{id:"meaning",title:"Meaning & contribution",desc:"Feeling that what you do matters or serves something important."},
{id:"enjoyment",title:"Enjoyment & excitement",desc:"Interest, pleasure, novelty or stimulation."}
];
const incentiveAvoid=[
{id:"loss",title:"Loss or insecurity",desc:"Losing money, stability, something you have, or something you depend on."},
{id:"uncertainty",title:"Uncertainty & instability",desc:"Not knowing what will happen or where you stand."},
{id:"stagnation",title:"Failure or stagnation",desc:"Falling behind, not progressing or feeling stuck."},
{id:"rejection",title:"Rejection or disapproval",desc:"Disappointing others, being excluded or judged negatively."},
{id:"control-loss",title:"Loss of freedom or control",desc:"Feeling trapped, dependent or unable to choose."},
{id:"regret",title:"Regret or missing out",desc:"Feeling that an opportunity passed you by."},
{id:"conflict",title:"Conflict or discomfort",desc:"Difficult conversations, tension, effort, disruption or emotional discomfort."}
];
const compoundGrow=[
{id:"knowledge",title:"Knowledge & expertise"},
{id:"skills",title:"Skills & capability"},
{id:"experience",title:"Experience & track record"},
{id:"reputation",title:"Reputation & credibility"},
{id:"relationships",title:"Relationships & network"},
{id:"financial",title:"Financial resources"},
{id:"health",title:"Health & personal capacity"},
{id:"optionality",title:"Freedom & optionality"}
];
const compoundAvoid=[
{id:"financial-pressure",title:"Financial pressure or obligations"},
{id:"dependence",title:"Dependence on one path, person, or condition"},
{id:"mental-load",title:"Ongoing stress or mental load"},
{id:"reduced-freedom",title:"Commitments that reduce your freedom"},
{id:"skill-neglect",title:"Neglect of important skills or capabilities"},
{id:"relationship-neglect",title:"Neglect of important relationships"},
{id:"health-damage",title:"Damage to health or personal capacity"},
{id:"hard-to-leave",title:"A path that becomes increasingly difficult to leave"}
];
const stressRows=[
{id:"money",label:"Money becomes tighter than expected"},
{id:"time",label:"The path takes longer than expected"},
{id:"capacity",label:"Your available energy or mental capacity is lower than expected"},
{id:"benefit",label:"The expected benefit is smaller or arrives later than expected"},
{id:"dependency",label:"Something important the path depends on does not materialise"},
{id:"external",label:"External circumstances turn against the plan"}
];
const stressChoices=[
{value:"manageable",label:"Manageable"},
{value:"limit",label:"At the limit"},
{value:"too-much",label:"Too much"}
];
const blankOption=name=>({id:uid(),name,trade:{foregone:[""],commitments:[""],foregoneState:"",foregoneUnknown:"",commitmentState:"",commitmentUnknown:""},incentives:{promises:[],avoid:[]},compound:{stronger:[],weaker:[],horizon:""},consequence:{positive:["","",""],negative:["","",""]},resilience:{conditions:[],financial:"maybe",time:"maybe",emotional:"maybe",strategic:"maybe"},reverse:{difficulty:0,costs:[],easier:""}});
function fresh(){return{decision:"",objective:"",inclination:"",horizon:"",options:[blankOption("Option A"),blankOption("Option B")],priorities:[],hasHardBoundaries:"",rules:[],incentiveConcerns:[],incentiveConcernNone:false,compounding:{grow:[],avoid:[],growDetails:{},growOptions:{},avoidDetails:{},avoidOptions:{}},inversion:[""],stressTest:{ratings:{},leastRoom:""},knowledge:[],judgment:{answers:{},strongestCase:"",changeEvidence:""},psych:[],factors:[],investigate:[],reviewed:[]}}
let data=(()=>{try{return JSON.parse(localStorage.getItem("clarity-v1"))||fresh()}catch{return fresh()}})();
if(!("inclination" in data))data.inclination="";
if(data.horizon==="Weeks"||data.horizon==="Months")data.horizon="Weeks or months";
if(data.horizon==="1–3 years")data.horizon="1–2 years";
if(data.horizon==="Longer")data.horizon="More than 5 years";
if(!Array.isArray(data.priorities))data.priorities=[];
if(!("hasHardBoundaries" in data))data.hasHardBoundaries=(data.rules&&data.rules.length)?"yes":"";
if(!Array.isArray(data.rules))data.rules=[];
data.rules.forEach(r=>{if(!r.status)r.status={};if(!r.investigate)r.investigate={};Object.keys(r.status).forEach(id=>{if(r.status[id]==="pass")r.status[id]="yes";if(r.status[id]==="fail")r.status[id]="no"})});
if(!Array.isArray(data.incentiveConcerns))data.incentiveConcerns=[];
if(!("incentiveConcernNone" in data))data.incentiveConcernNone=false;
if(!data.compounding)data.compounding={grow:[],avoid:[],growDetails:{},growOptions:{},avoidDetails:{},avoidOptions:{}};
if(!Array.isArray(data.compounding.grow))data.compounding.grow=[];
if(!Array.isArray(data.compounding.avoid))data.compounding.avoid=[];
if(!data.compounding.growDetails)data.compounding.growDetails={};
if(!data.compounding.growOptions)data.compounding.growOptions={};
if(!data.compounding.avoidDetails)data.compounding.avoidDetails={};
if(!data.compounding.avoidOptions)data.compounding.avoidOptions={};
if(!Array.isArray(data.inversion))data.inversion=[""];
if(!data.stressTest)data.stressTest={ratings:{},leastRoom:""};
if(!data.stressTest.ratings)data.stressTest.ratings={};
if(!("leastRoom" in data.stressTest))data.stressTest.leastRoom="";
if(!data.judgment)data.judgment={answers:{},strongestCase:"",changeEvidence:""};
if(!data.judgment.answers)data.judgment.answers={};
if(!("strongestCase" in data.judgment))data.judgment.strongestCase="";
if(!("changeEvidence" in data.judgment))data.judgment.changeEvidence="";
data.options.forEach(o=>{
  if(!o.incentives)o.incentives={};
  if(!Array.isArray(o.incentives.promises)){
    const old=Array.isArray(o.incentives.internal)?o.incentives.internal:[];
    const map={Money:"financial",Security:"security",Status:"recognition",Approval:"recognition",Belonging:"belonging",Autonomy:"freedom",Excitement:"enjoyment"};
    o.incentives.promises=[...new Set(old.map(x=>map[x]).filter(Boolean))];
  }
  if(!Array.isArray(o.incentives.avoid)){
    const old=Array.isArray(o.incentives.internal)?o.incentives.internal:[];
    const map={"Fear of loss":"loss","Fear of regret":"regret"};
    o.incentives.avoid=[...new Set(old.map(x=>map[x]).filter(Boolean))];
  }
  if(!o.trade)o.trade={};
  if(!Array.isArray(o.trade.foregone)){
    const old=Array.isArray(o.trade.reject)?o.trade.reject.filter(Boolean):[];
    o.trade.foregone=old.length?old:[""];
  }
  if(!Array.isArray(o.trade.commitments)){
    const old=Array.isArray(o.trade.costs)?o.trade.costs.filter(Boolean):[];
    o.trade.commitments=old.length?old:[""];
  }
  if(!("foregoneState" in o.trade))o.trade.foregoneState="";
  if(!("foregoneUnknown" in o.trade))o.trade.foregoneUnknown="";
  if(!("commitmentState" in o.trade))o.trade.commitmentState="";
  if(!("commitmentUnknown" in o.trade))o.trade.commitmentUnknown="";
  if(!o.consequence)o.consequence={positive:["","",""],negative:["","",""],expanded:{positive:false,negative:false}};
  ["positive","negative"].forEach(k=>{
    if(!Array.isArray(o.consequence[k]))o.consequence[k]=["","",""];
    while(o.consequence[k].length<3)o.consequence[k].push("");
  });
  if(!o.consequence.expanded)o.consequence.expanded={
    positive:Boolean(o.consequence.positive[2]),
    negative:Boolean(o.consequence.negative[2])
  };
});
let step=Math.max(0,Math.min(11,data.ui?.step||0)),active=data.options.some(o=>o.id===data.ui?.active)?data.ui.active:data.options[0].id,incentiveReview=Boolean(data.ui?.incentiveReview),selectedReflections=[];
if(!data.reviewed)data.reviewed=[];
data.factors.forEach(f=>{if(!Array.isArray(f.options))f.options=f.option?[f.option]:[];if(!Array.isArray(f.sources))f.sources=[];});
function save(){data.ui={step,active,incentiveReview};localStorage.setItem("clarity-v1",JSON.stringify(data))}
function option(){return data.options.find(o=>o.id===active)||data.options[0]}
function setOptName(id,v){data.options.find(o=>o.id===id).name=v;save()}
function list(items,path,placeholder){return '<div class="list">'+items.map((x,i)=>'<div class="item"><input data-list="'+path+'" data-i="'+i+'" value="'+esc(x)+'" placeholder="'+esc(placeholder)+'"><button class="x" data-del="'+path+'" data-i="'+i+'">×</button></div>').join("")+'<button class="add" data-add="'+path+'">+ Add</button></div>'}
function getPath(path){return path.split(".").reduce((o,k)=>o[k],data)}
function setPath(path,val){const p=path.split(".");let o=data;for(let i=0;i<p.length-1;i++)o=o[p[i]];o[p.at(-1)]=val}
function tabs(){return '<div class="tabs">'+data.options.map(o=>'<button data-tab="'+o.id+'" class="'+(o.id===active?"active":"")+'">'+esc(o.name)+'</button>').join("")+'</div>'}
function card(title,sub,body){return '<div class="card"><h2>'+title+'</h2><p class="muted">'+sub+'</p>'+body+'</div>'}
function render(){
 save();$("#title").textContent=steps[step];$("#stepCount").textContent=(step+1)+" of "+steps.length;
 $("#bar").style.width=((step+1)/steps.length*100)+"%";
 $("#nav").innerHTML=steps.map((name,i)=>'<button data-step="'+i+'" class="'+(i===step?'active':'')+'" '+(i===step?'aria-current="step"':'')+'><span>'+name+'</span><small aria-label="'+(data.reviewed.includes(i)?'Reviewed':'Not reviewed')+'">'+(data.reviewed.includes(i)?'✓':'')+'</small></button>').join('');
 $("#back").disabled=step===0;$("#next").style.display=step===11?'none':'block';
 const oi=data.options.findIndex(o=>o.id===active);
 $("#next").textContent=[2,3,5,9].includes(step)&&!(step===3&&incentiveReview)&&oi<data.options.length-1?'Continue to '+data.options[oi+1].name+' →':step===3&&!incentiveReview?'Review incentives →':step===10?'Continue to Decision Overview →':'Continue →';
 $("#screen").innerHTML=screen();
 document.querySelectorAll('.card > h2,.decision-overview > h2').forEach(h=>{if(h.textContent===steps[step])h.remove();});
 document.querySelectorAll('.trade-option-nav').forEach(n=>n.remove());
 document.querySelectorAll('.x').forEach(b=>b.setAttribute('aria-label','Remove item'));
 bind();
}
function screen(){if(step===0)return frame();if(step===1)return boundaries();if(step===2)return tradeoffs();if(step===3)return incentives();if(step===4)return compounding();if(step===5)return consequences();if(step===6)return inversion();if(step===7)return stressTest();if(step===8)return judgmentCheck();if(step===9)return reversibility();if(step===10)return factors();return decisionOverview()}
function frame(){const horizons=["Weeks or months","1–2 years","3–5 years","More than 5 years","Potentially permanent","Not sure"];return '<div class="card decision-card"><p class="muted intro">Start by defining the choice you are facing, the realistic paths available to you, and what you ultimately want this decision to achieve.</p><label class="field"><span>What decision are you trying to make?</span><small>Write it as the choice you are actually facing.</small><textarea data-root="decision" placeholder="e.g. Should I move to a new city or stay where I am?">'+esc(data.decision)+'</textarea></label><div class="decision-block"><div class="question">What are the realistic options you are considering?</div>'+data.options.map((o,i)=>'<div class="row"><b>'+String.fromCharCode(65+i)+'</b><input data-optname="'+o.id+'" value="'+esc(o.name)+'" placeholder="Describe option '+String.fromCharCode(65+i)+'"><button class="x" data-removeopt="'+o.id+'">×</button></div>').join("")+'<button class="add" id="addOpt">+ Add another option</button></div><div class="divider"></div><label class="field"><span>In the bigger picture, what are you ultimately hoping this decision will help you achieve?</span><small>Look beyond the immediate outcome. What are you trying to make better, possible, or different?</small><textarea data-root="objective" placeholder="Describe the bigger outcome you are trying to create.">'+esc(data.objective)+'</textarea></label><div class="divider"></div><div class="decision-block"><div class="question">Before thinking it through further, do you already feel more inclined toward one option?</div><p class="field-note">This is only your starting point. It will not determine where your reasoning eventually leads.</p><div class="choice-grid">'+data.options.map(o=>'<label class="choice-card"><input type="radio" name="inclination" data-inclination value="'+o.id+'" '+(data.inclination===o.id?"checked":"")+'><span>'+esc(o.name||"Untitled option")+'</span></label>').join("")+'<label class="choice-card"><input type="radio" name="inclination" data-inclination value="none" '+(data.inclination==="none"?"checked":"")+'><span>No clear inclination yet</span></label></div></div><div class="divider"></div><div class="decision-block"><div class="question">How long could the consequences of this decision meaningfully affect you?</div><div class="choice-grid compact">'+horizons.map(x=>'<label class="choice-card"><input type="radio" name="horizon" data-horizon value="'+x+'" '+(data.horizon===x?"checked":"")+'><span>'+x+'</span></label>').join("")+'</div></div></div>'}
function boundaries(){
const selected=data.priorities.length,locked=selected>=3;
const domains=lifeDomains.map(d=>'<label class="domain-card '+(data.priorities.includes(d.id)?"selected":"")+'"><input type="checkbox" data-priority value="'+d.id+'" '+(data.priorities.includes(d.id)?"checked":"")+' '+(locked&&!data.priorities.includes(d.id)?"disabled":"")+'><div><strong>'+esc(d.title)+'</strong><p>'+esc(d.desc)+'</p></div></label>').join("");
const hardChoice='<div class="choice-grid hard-choice"><label class="choice-card"><input type="radio" name="hardboundaries" data-hardboundaries value="no" '+(data.hasHardBoundaries==="no"?"checked":"")+'><span>No hard boundaries</span></label><label class="choice-card"><input type="radio" name="hardboundaries" data-hardboundaries value="yes" '+(data.hasHardBoundaries==="yes"?"checked":"")+'><span>Yes, I have one or more</span></label></div>';
const boundaryList=data.hasHardBoundaries==="yes"?'<div class="divider"></div><div class="boundary-intro"><h3>Your hard boundaries</h3><p class="muted">Think about the decision as a whole, not one option at a time.</p><div class="question">What must remain true, or what must not happen, regardless of which path you choose?</div><p class="field-note">Write one boundary at a time. Be as concrete as you can.</p></div>'+data.rules.map((r,ri)=>'<div class="boundary-card"><div class="boundary-head"><span>BOUNDARY '+String(ri+1).padStart(2,"0")+'</span><button class="x" data-delrule="'+r.id+'">×</button></div><textarea data-rule="'+r.id+'" placeholder="e.g. I need the choice to remain compatible with an existing responsibility I cannot give up.">'+esc(r.text)+'</textarea><div class="boundary-check-title">Now check each option against this boundary.</div>'+data.options.map(o=>{const s=r.status[o.id]||"";return '<div class="boundary-option"><strong>'+esc(o.name||"Untitled option")+'</strong><div class="question">Does this option stay within the boundary?</div><div class="boundary-status"><label><input type="radio" name="boundary-'+r.id+'-'+o.id+'" data-rulestatus="'+r.id+'" data-oid="'+o.id+'" value="yes" '+(s==="yes"?"checked":"")+'><span>Yes, it stays within it</span></label><label><input type="radio" name="boundary-'+r.id+'-'+o.id+'" data-rulestatus="'+r.id+'" data-oid="'+o.id+'" value="unknown" '+(s==="unknown"?"checked":"")+'><span>I’m not sure yet</span></label><label><input type="radio" name="boundary-'+r.id+'-'+o.id+'" data-rulestatus="'+r.id+'" data-oid="'+o.id+'" value="no" '+(s==="no"?"checked":"")+'><span>No, it crosses the boundary</span></label></div>'+(s==="unknown"?'<label class="field uncertainty-field"><span>What do you need to find out?</span><textarea data-ruleinvestigate="'+r.id+'" data-oid="'+o.id+'">'+esc(r.investigate[o.id]||"")+'</textarea><small>This will be carried forward to what you still need to find out.</small></label>':"")+'</div>'}).join("")+'</div>').join("")+'<button id="addRule" class="secondary">+ Add another hard boundary</button>':"";
return '<div class="card what-matters-card"><p class="muted intro">Before comparing the options, identify what this decision most needs to protect, improve, or make possible.</p><div class="decision-block"><div class="question">Which parts of your life matter most in this decision?</div><p class="field-note">Choose up to three. Think about the areas that would matter most when you eventually judge whether this decision worked out well for you.</p><div class="domain-grid">'+domains+'</div><div class="selection-count">'+selected+' of 3 selected</div></div><div class="divider"></div><div class="decision-block"><div class="question">Do you have any hard boundaries for this decision?</div><p class="field-note boundary-definition">A hard boundary is a condition that every acceptable option must respect. It can be something that must remain true, or something that must not happen.<br><br>If enough upside elsewhere could make you compromise on it, it is not a hard boundary. We will weigh it later as a trade-off.</p>'+hardChoice+'</div>'+boundaryList+'</div>'
}

function tradeoffs(){
const o=option(),oi=data.options.indexOf(o),num=oi+1,total=data.options.length;
const selectedDomains=data.priorities.map(id=>lifeDomains.find(d=>d.id===id)).filter(Boolean);
const hasForegone=(o.trade.foregone||[]).some(x=>String(x).trim());
const hasCommitments=(o.trade.commitments||[]).some(x=>String(x).trim());
const domainReminder=selectedDomains.length?'<div class="trade-reminder"><span>Earlier, you said these areas matter most:</span><div class="chips static-chips">'+selectedDomains.map(d=>'<span class="chip">'+esc(d.title)+'</span>').join("")+'</div><small>Keep them in mind as you think, but include anything else that genuinely matters.</small></div>':"";
const alternatives=(kind,state)=>'<div class="trade-alternatives"><span>If neither applies, you can say:</span><label><input type="radio" name="'+kind+'-state" data-tradestate="'+kind+'" value="none" '+(state==="none"?"checked":"")+'><span>I can’t identify anything meaningful yet</span></label><label><input type="radio" name="'+kind+'-state" data-tradestate="'+kind+'" value="unknown" '+(state==="unknown"?"checked":"")+'><span>I don’t know enough yet</span></label></div>';
const unknownField=(kind,value)=>'<label class="field trade-unknown"><span>What do you need to find out?</span><textarea data-tradeunknown="'+kind+'">'+esc(value||"")+'</textarea><small>This will be carried forward to what you still need to find out.</small></label>';
const resources=[
["Time","The hours, days, or years this path could require."],
["Money","Income, savings, capital, or financial capacity it could commit."],
["Energy","Physical or emotional capacity it could demand."],
["Mental bandwidth","Focus, headspace, planning, or ongoing mental load it could occupy."],
["Flexibility","Your room to change direction, relocate, adjust commitments, or take another opportunity later."]
];
const nav='<div class="trade-option-nav">'+(oi>0?'<button class="secondary" data-tradeprev>← Previous option</button>':'<span></span>')+(oi<total-1?'<button data-tradenext>Continue to Option '+(num+1)+' →</button>':'<span class="field-note">You’ve considered each option. Continue when you’re ready.</span>')+'</div>';
return '<div class="card trade-card"><p class="muted intro">Every choice closes off something else.</p><p class="muted trade-lead">Consider each option in turn. You do not need to prefer it. Just suppose it is the path you take and look at what that choice would require you to give up.</p>'+domainReminder+'<div class="divider"></div><div class="trade-option-count">OPTION '+num+' OF '+total+'</div><div class="trade-suppose"><span>Suppose you take:</span><strong>'+esc(o.name||"Untitled option")+'</strong></div><div class="trade-question"><div class="question">What valuable things would become unavailable, harder to pursue, or delayed?</div><p class="field-note">Consider what the other options could have given you.</p>'+list(o.trade.foregone,'options.'+oi+'.trade.foregone',"A meaningful opportunity, benefit, freedom, relationship, or future path")+(hasForegone?"":alternatives("foregone",o.trade.foregoneState))+(o.trade.foregoneState==="unknown"&&!hasForegone?unknownField("foregone",o.trade.foregoneUnknown):"")+'</div><div class="divider"></div><div class="trade-question"><div class="question">What would this path require from you or tie up?</div><p class="field-note">Use these as prompts. You only need to record the costs that are meaningful for this decision.</p><div class="resource-grid">'+resources.map(([t,d])=>'<div class="resource-prompt"><strong>'+t+'</strong><span>'+d+'</span></div>').join("")+'</div>'+list(o.trade.commitments,'options.'+oi+'.trade.commitments',"A meaningful cost, demand, or constraint")+(hasCommitments?"":alternatives("commitment",o.trade.commitmentState))+(o.trade.commitmentState==="unknown"&&!hasCommitments?unknownField("commitment",o.trade.commitmentUnknown):"")+'</div>'+nav+'</div>'
}
function incentives(){
const o=option(),oi=data.options.indexOf(o),num=oi+1,total=data.options.length;
const allChoices=[...incentivePromises,...incentiveAvoid];
const selectedIds=[...new Set(data.options.flatMap(x=>[...(x.incentives?.promises||[]),...(x.incentives?.avoid||[])]))];
if(incentiveReview){
  const rows=selectedIds.map(id=>{const c=allChoices.find(x=>x.id===id);if(!c)return"";const names=data.options.filter(x=>(x.incentives.promises||[]).includes(id)||(x.incentives.avoid||[]).includes(id)).map(x=>x.name||"Untitled option");return '<label class="incentive-summary-row"><input type="checkbox" data-incentiveconcern value="'+id+'" '+(data.incentiveConcerns.includes(id)?"checked":"")+'><div><strong>'+esc(c.title)+'</strong><span>→ '+esc(names.join(", "))+'</span></div></label>'}).join("");
  return '<div class="card incentive-card"><p class="muted intro">Our choices are pulled by things we expect to gain and pushed by things we want to avoid.</p><p class="muted incentive-explainer">Some are practical, like money or security. Others are psychological, like recognition, belonging, freedom, or relief from uncertainty. The point here is not to judge these motives. It is to make visible what may be pulling you toward each path.</p><div class="divider"></div><div class="trade-option-count">LOOKING ACROSS THE DECISION</div><h3>These are some of the forces pulling on your choice.</h3>'+(rows||'<p class="muted">You have not selected any incentives yet.</p>')+(rows?'<div class="divider"></div><div class="question">Is any of this something you would not want to keep letting drive similar decisions over time?</div><p class="field-note">Select anything that gives you pause.</p><div class="incentive-summary-list">'+rows+'</div><label class="incentive-none"><input type="checkbox" data-incentivenone '+(data.incentiveConcernNone?"checked":"")+'><span>None of these concern me</span></label>':"")+'<div class="trade-option-nav"><button class="secondary" data-incentiveback>← Back to Option '+total+'</button><span class="field-note">Continue when you are ready.</span></div></div>';
}
const cards=(choices,key)=>'<div class="incentive-grid">'+choices.map(c=>'<label class="incentive-choice '+((o.incentives[key]||[]).includes(c.id)?"selected":"")+'"><input type="checkbox" data-incentive="'+key+'" value="'+c.id+'" '+((o.incentives[key]||[]).includes(c.id)?"checked":"")+'><div><strong>'+esc(c.title)+'</strong><p>'+esc(c.desc)+'</p></div></label>').join("")+'</div>';
const nav='<div class="trade-option-nav">'+(oi>0?'<button class="secondary" data-incentiveprev>← Previous option</button>':'<span></span>')+(oi<total-1?'<button data-incentivenext>Continue to Option '+(num+1)+' →</button>':'<button data-incentivereview>Review this decision →</button>')+'</div>';
return '<div class="card incentive-card"><p class="muted intro">Our choices are pulled by things we expect to gain and pushed by things we want to avoid.</p><p class="muted incentive-explainer">Some are practical, like money or security. Others are psychological, like recognition, belonging, freedom, or relief from uncertainty. The point here is not to judge these motives. It is to make visible what may be pulling you toward each path.</p><div class="divider"></div><div class="trade-option-count">OPTION '+num+' OF '+total+'</div><div class="trade-suppose"><span>Suppose you take</span><strong>'+esc(o.name||"Untitled option")+'</strong></div><div class="question">What does this path promise you?</div><p class="field-note">Select anything that meaningfully pulls you toward this option.</p>'+cards(incentivePromises,"promises")+'<div class="divider"></div><div class="question">What does this path help you get away from or avoid?</div><p class="field-note">Select anything that meaningfully pushes you toward this option.</p>'+cards(incentiveAvoid,"avoid")+nav+'</div>'
}
function compounding(){
const c=data.compounding;
const growLocked=c.grow.length>=3,avoidLocked=c.avoid.length>=3;
const categoryGrid=(items,selected,key,locked)=>'<div class="compound-grid">'+items.map(x=>'<label class="compound-choice '+(selected.includes(x.id)?"selected":"")+'"><input type="checkbox" data-compoundselect="'+key+'" value="'+x.id+'" '+(selected.includes(x.id)?"checked":"")+' '+(locked&&!selected.includes(x.id)?"disabled":"")+'><span>'+esc(x.title)+'</span></label>').join("")+'</div><div class="selection-count">'+selected.length+' of 3 selected</div>';
const optionChecks=(kind,id)=>'<div class="compound-options">'+data.options.map(o=>'<label><input type="checkbox" data-compoundoption="'+kind+'" data-compoundid="'+id+'" value="'+o.id+'" '+(((c[kind+"Options"][id]||[]).includes(o.id))?"checked":"")+'><span>'+esc(o.name||"Untitled option")+'</span></label>').join("")+'</div>';
const growDetails=c.grow.map(id=>{const item=compoundGrow.find(x=>x.id===id);if(!item)return"";return '<div class="compound-detail"><div class="compound-detail-title">'+esc(item.title)+'</div><label class="field"><span>What specifically are you hoping to build?</span><input data-compounddetail="grow" data-compoundid="'+id+'" value="'+esc(c.growDetails[id]||"")+'"></label><div class="question">Which path would meaningfully build this over time?</div>'+optionChecks("grow",id)+'</div>'}).join("");
const avoidDetails=c.avoid.map(id=>{const item=compoundAvoid.find(x=>x.id===id);if(!item)return"";return '<div class="compound-detail"><div class="compound-detail-title">'+esc(item.title)+'</div><label class="field"><span>What specifically are you trying to avoid accumulating?</span><input data-compounddetail="avoid" data-compoundid="'+id+'" value="'+esc(c.avoidDetails[id]||"")+'"></label><div class="question">Which path is most likely to compound this over time?</div>'+optionChecks("avoid",id)+'</div>'}).join("");
return '<div class="card compound-card"><p class="muted intro">Some effects of a decision do not happen all at once.</p><p class="muted compound-lead">What you repeatedly invest in can build over time. What you repeatedly reinforce can gradually shape the direction you are moving in.</p><div class="goal-callout"><span>You said you ultimately want this decision to help you:</span><strong>'+esc(data.objective||"No bigger outcome entered yet.")+'</strong></div><div class="divider"></div><div class="question">What are you hoping to meaningfully grow through this decision?</div><p class="field-note">Choose up to three.</p>'+categoryGrid(compoundGrow,c.grow,"grow",growLocked)+growDetails+'<div class="divider"></div><div class="question">What are you especially trying not to let accumulate or become harder to undo through this decision?</div><p class="field-note">Choose up to three.</p>'+categoryGrid(compoundAvoid,c.avoid,"avoid",avoidLocked)+avoidDetails+'</div>'
}
function consequences(){
const o=option(),oi=data.options.indexOf(o),num=oi+1,total=data.options.length;
const matters=data.priorities.map(id=>lifeDomains.find(d=>d.id===id)?.title).filter(Boolean);
const mattersHtml=matters.length?'<div class="chain-matters"><span>As you think through the effects, keep these in view:</span><div class="chain-matter-chips">'+matters.map(x=>'<span>'+esc(x)+'</span>').join("")+'</div></div>':'';
const rail=(key,title,prompt)=>{
  const a=o.consequence[key]||["","",""],expanded=o.consequence.expanded&&o.consequence.expanded[key];
  return '<div class="chain-block"><div class="chain-kicker">'+title+'</div><div class="question">'+prompt+'</div><div class="chain-rail"><div class="chain-origin">THIS CHOICE</div><div class="chain-arrow">→</div><label class="chain-node"><span>What changes first?</span><input data-chain="'+key+'" data-i="0" value="'+esc(a[0]||"")+'"></label><div class="chain-arrow">→</div><label class="chain-node"><span>What could that change next?</span><input data-chain="'+key+'" data-i="1" value="'+esc(a[1]||"")+'"></label><div class="chain-arrow">→</div>'+(expanded?'<label class="chain-node"><span>What could that eventually affect?</span><input data-chain="'+key+'" data-i="2" value="'+esc(a[2]||"")+'"></label>':'<button class="chain-add" data-chainexpand="'+key+'">+ Add one more step</button>')+'</div></div>';
};
const nav='<div class="trade-option-nav">'+(oi>0?'<button class="secondary" data-chainprev>← Previous option</button>':'<span></span>')+(oi<total-1?'<button data-chainnext>Continue to Option '+(num+1)+' →</button>':'<button data-chaincontinue>Continue →</button>')+'</div>';
return '<div class="card chain-card"><p class="muted intro">The first consequence is rarely the whole consequence.</p><p class="muted chain-lead">Trace what could happen next, then what that could lead to.</p><p class="chain-stop">Stop when the next step would mostly be a guess.</p>'+mattersHtml+'<div class="divider"></div><div class="trade-option-count">OPTION '+num+' OF '+total+'</div><div class="trade-suppose"><span>Suppose you take</span><strong>'+esc(o.name||"Untitled option")+'</strong></div>'+rail("positive","A PLAUSIBLE UPSIDE CHAIN","Trace one important way this choice could work in your favour.")+'<div class="divider"></div>'+rail("negative","A PLAUSIBLE DOWNSIDE CHAIN","Now trace one important way this choice could work against you.")+'<p class="chain-stop bottom">Stop when the next step would mostly be a guess.</p>'+nav+'</div>'
}
function inversion(){
const rows=(data.inversion||[""]).map((x,i)=>'<div class="inversion-item"><input data-list="inversion" data-i="'+i+'" value="'+esc(x)+'"><button class="x" data-del="inversion" data-i="'+i+'">×</button></div>').join("");
return '<div class="card inversion-card"><h2>Inversion</h2><p class="muted intro">Instead of asking only how this decision could work,<br>look at what could make it fail.</p><div class="goal-callout"><span>You said you ultimately want this decision to help you:</span><strong>'+esc(data.objective||"No bigger outcome entered yet.")+'</strong></div><div class="divider"></div><div class="question">What would make this decision fail to achieve that?</div><div class="inversion-list">'+rows+'<button class="add" data-add="inversion">+ Add another</button></div></div>'
}
function stressTest(){
const ratings=data.stressTest.ratings||{};
const choiceOptions=value=>'<option value="">Select ▾</option>'+stressChoices.map(c=>'<option value="'+c.value+'" '+(value===c.value?"selected":"")+'>'+c.label+'</option>').join("");
const head='<tr><th class="stress-scenario"></th>'+data.options.map(o=>'<th>'+esc(o.name||"Untitled option")+'</th>').join("")+'</tr>';
const body=stressRows.map(r=>'<tr><th class="stress-scenario">'+esc(r.label)+'</th>'+data.options.map(o=>{const v=(ratings[r.id]&&ratings[r.id][o.id])||"";return '<td><select data-stressrow="'+r.id+'" data-stressoption="'+o.id+'">'+choiceOptions(v)+'</select></td>'}).join("")+'</tr>').join("");
return '<div class="card stress-card"><h2>Stress Test</h2><p class="muted intro">A decision can look strong when things go roughly as expected.</p><p class="muted stress-lead">Now make some important conditions less favourable and see<br>how much pressure each option could absorb.</p><div class="stress-legend"><div><strong>Can absorb</strong><span>The option should remain workable.</span></div><div><strong>Strained</strong><span>It may still work, but with little room for further problems.</span></div><div><strong>Beyond tolerance</strong><span>The option could become unworkable or unacceptable.</span></div></div><div class="divider"></div><div class="stress-table-wrap"><table class="stress-table"><thead>'+head+'</thead><tbody>'+body+'</tbody></table></div><div class="divider"></div><label class="field stress-summary"><span>Where does this decision seem to have the least room for things going wrong?</span><textarea data-stresssummary>'+esc(data.stressTest.leastRoom||"")+'</textarea></label></div>'
}
function judgmentConditionalRows(){
const promises=new Set(data.options.flatMap(o=>o.incentives?.promises||[]));
const avoid=new Set(data.options.flatMap(o=>o.incentives?.avoid||[]));
const ids=[];
if(promises.has("recognition"))ids.push("seen");
if(promises.has("belonging")||avoid.has("rejection"))ids.push("social");
if(promises.has("security")||avoid.has("uncertainty"))ids.push("uncertainty");
return judgmentConditional.filter(x=>ids.includes(x.id))
}
function judgmentTable(rows){
const answer=id=>data.judgment.answers[id]||"";
return '<div class="judgment-table-wrap"><table class="judgment-table"><thead><tr><th></th><th>No</th><th>Maybe</th><th>Yes</th></tr></thead><tbody>'+rows.map(r=>'<tr><td>'+esc(r.question)+'</td>'+["no","maybe","yes"].map(v=>'<td><label class="judgment-radio"><input type="radio" name="judgment-'+r.id+'" data-judgment="'+r.id+'" aria-label="'+esc(r.question+' — '+v)+'" value="'+v+'" '+(answer(r.id)===v?"checked":"")+'><span></span></label></td>').join("")+'</tr>').join("")+'</tbody></table></div>'
}
function judgmentCheck(){
const conditional=judgmentConditionalRows();
return '<div class="card judgment-card"><h2>Judgment Check</h2><p class="muted intro">Some influences can quietly change how you see a decision.</p><p class="muted judgment-lead">Mentally remove each one and notice whether your judgment changes.</p><div class="judgment-key"><span><strong>NO</strong>I’d see it the same way</span><span><strong>MAYBE</strong>I’m not sure</span><span><strong>YES</strong>I’d see it differently</span></div><div class="divider"></div>'+judgmentTable(judgmentCore)+'<div class="divider"></div><div class="judgment-challenge"><div class="judgment-challenge-row"><label>What is the strongest serious case that the way you currently see this decision could be wrong?</label><textarea data-judgmenttext="strongestCase">'+esc(data.judgment.strongestCase||"")+'</textarea></div><div class="judgment-challenge-row"><label>What evidence would most seriously change your view?</label><textarea data-judgmenttext="changeEvidence">'+esc(data.judgment.changeEvidence||"")+'</textarea></div></div>'+(conditional.length?'<div class="divider"></div><p class="muted conditional-intro">A few additional things are worth checking based on what came up earlier in your decision.</p>'+judgmentTable(conditional):"")+'</div>'
}
function reversibility(){const o=option();return card("If you are wrong, how hard is it to change course?","The harder a choice is to undo, the more evidence and margin of safety it deserves.",tabs()+'<label class="field"><span>How difficult would this option be to reverse?</span><select data-difficulty><option value="0">Not assessed</option>'+[[1,"Easy"],[2,"Moderate"],[3,"Difficult"]].map(([v,l])=>'<option value="'+v+'" '+(o.reverse.difficulty===v?"selected":"")+'>'+l+'</option>').join("")+'</select></label><div class="section">What would reversing it cost?</div><div class="chips">'+["Time","Money","Relationships","Reputation","Legal / contractual cost","Lost opportunity","Emotional cost"].map(x=>'<button class="chip '+(o.reverse.costs.includes(x)?"active":"")+'" data-revcost="'+x+'">'+x+'</button>').join("")+'</div><label class="field"><span>Could you structure the choice to make it easier to reverse?</span><textarea data-optfield="reverse.easier">'+esc(o.reverse.easier)+'</textarea></label>')}
function driverOptions(f){return (f.options||[]).filter(id=>data.options.some(o=>o.id===id));}
function driverDirection(f){const ids=driverOptions(f);return ids.length?'Supports '+ids.map(id=>data.options.find(o=>o.id===id).name).join(' and '):f.directionAssessed?'No clear difference':'Direction not assessed';}
function reflections(){
 const rows=[];const add=(id,text,optionId)=>{if(text?.trim())rows.push({id,text:text.trim(),optionId});};
 data.options.forEach(o=>{['foregone','commitments'].forEach(k=>(o.trade[k]||[]).forEach((t,i)=>add(o.id+'-trade-'+k+'-'+i,t,o.id)));['positive','negative'].forEach(k=>(o.consequence[k]||[]).filter(Boolean).forEach((t,i)=>add(o.id+'-chain-'+k+'-'+i,t,o.id)));[...(o.incentives.promises||[]),...(o.incentives.avoid||[])].forEach(id=>add(o.id+'-motive-'+id,[...incentivePromises,...incentiveAvoid].find(x=>x.id===id)?.title,o.id));});
 ['grow','avoid'].forEach(k=>data.compounding[k].forEach(id=>add('compound-'+k+'-'+id,data.compounding[k+'Details'][id],null)));
 data.inversion.forEach((text,i)=>add('inversion-'+i,text,null));
 return rows;
}
function factors(){
 const rows=reflections();const used=new Set(data.factors.flatMap(f=>(f.sources||[]).map(x=>x.id)));
 const reference=rows.length?rows.map(r=>'<label class="reflection-row"><input type="checkbox" data-reflection="'+esc(r.id)+'" '+(selectedReflections.includes(r.id)?'checked':'')+'><span>'+esc(r.text)+'<small>'+esc(data.options.find(o=>o.id===r.optionId)?.name||'Across the decision')+(used.has(r.id)?' · Already linked':'')+'</small></span></label>').join(''):'<p class="muted">Your earlier answers will appear here. You can also add a driver directly.</p>';
 const controls=(f,key,label,choices)=>'<label class="field"><span>'+label+'</span><select data-factor="'+f.id+'" data-key="'+key+'"><option value="0">Choose…</option>'+choices.map(([v,l])=>'<option value="'+v+'" '+(f[key]===v?'selected':'')+'>'+l+'</option>').join('')+'</select></label>';
 const editors=data.factors.map(f=>'<article class="factor"><div class="factorhead"><input aria-label="Driver name" data-factor="'+f.id+'" data-key="name" value="'+esc(f.name)+'" placeholder="Name this decision driver"><button class="x" data-delfactor="'+f.id+'" aria-label="Remove driver">×</button></div><p class="field-note">'+(f.sources||[]).length+' linked reflection'+((f.sources||[]).length===1?'':'s')+'</p><fieldset class="driver-direction"><legend>Which paths does this support?</legend><div class="compound-options">'+data.options.map(o=>'<label><input type="checkbox" data-driveroption="'+f.id+'" value="'+o.id+'" '+(driverOptions(f).includes(o.id)?'checked':'')+'><span>'+esc(o.name)+'</span></label>').join('')+'<label><input type="checkbox" data-drivernone="'+f.id+'" '+(f.directionAssessed&&!driverOptions(f).length?'checked':'')+'><span>No clear difference</span></label></div></fieldset><div class="metricgrid">'+controls(f,'importance','Importance',[[1,'Low'],[2,'Medium'],[3,'High']])+controls(f,'evidence','Evidence',[[1,'Assumption'],[2,'Reasonable estimate'],[3,'Verified fact']])+controls(f,'strength','How strongly?',[[1,'Somewhat'],[2,'Strongly']])+'</div><label class="field"><span>Why this matters</span><textarea data-factor="'+f.id+'" data-key="rationale">'+esc(f.rationale)+'</textarea></label>'+((f.sources||[]).length?'<details><summary>Review supporting reflections</summary><ul>'+f.sources.map(r=>'<li>'+esc(r.text)+'</li>').join('')+'</ul></details>':'')+'</article>').join('');
 return '<div class="drivers-page"><p class="muted">Bring related reasons together. Assess each once.</p>'+decisionAnchor()+'<div class="drivers-workspace"><section class="reflection-panel"><h2>Your earlier reflections</h2><p class="field-note">Select related reflections to group into one driver.</p>'+reference+'<button id="groupReflections" '+(!selectedReflections.length?'disabled':'')+'>Create driver from '+selectedReflections.length+' reflection'+(selectedReflections.length===1?'':'s')+'</button></section><section class="driver-editors">'+(editors||'<div class="empty-state"><h2>What are the real reasons?</h2><p>Select related reflections, or add a driver directly. Aim for a few distinct reasons rather than repeating the same one.</p></div>')+'<button id="addFactor" class="secondary">+ Add a decision driver</button></section></div></div>';
}
function decisionAnchor(){return '<div class="decision-anchor"><small>DECISION</small><p>'+esc(data.decision||'Your decision is not defined yet.')+'</p></div>';}
function assessmentComplete(){return Boolean(data.decision.trim()&&data.objective.trim()&&data.hasHardBoundaries&&data.priorities.length&&data.reviewed.filter(i=>i<11).length===11&&data.options.every(o=>o.reverse.difficulty>0)&&data.factors.length&&data.factors.every(f=>f.name.trim()&&f.importance&&f.evidence&&f.strength&&(f.directionAssessed||driverOptions(f).length))&&stressRows.every(r=>data.options.every(o=>data.stressTest.ratings[r.id]?.[o.id])));}

function analyse(){
 const scores=Object.fromEntries(data.options.map(o=>[o.id,0]));
 const assessed=data.factors.filter(f=>f.name.trim()&&f.importance&&f.evidence&&f.strength&&(driverOptions(f).length||f.directionAssessed));
 assessed.forEach(f=>driverOptions(f).forEach(id=>scores[id]+=f.strength*f.importance*f.evidence));
 const sorted=[...data.options].sort((a,b)=>scores[b.id]-scores[a.id]);const top=sorted[0],second=sorted[1];const total=Object.values(scores).reduce((a,b)=>a+b,0)||1;const gap=(scores[top.id]-scores[second.id])/total;
 const lean=!assessed.length?'Not assessed':gap<.08?'No clear lean':gap<.22?'Slight lean toward '+top.name:'Moderate lean toward '+top.name;
 const rules=data.hasHardBoundaries==='yes'?data.rules:[];
 const fails=rules.some(r=>data.options.some(o=>r.status[o.id]==='no'));
 const unresolvedBoundary=rules.some(r=>!r.text.trim()||data.options.some(o=>!r.status[o.id]||r.status[o.id]==='unknown'));
 const assumptions=assessed.filter(f=>f.importance===3&&f.evidence===1).length;
 const complete=assessmentComplete();const unresolved=allInvestigations().length;
 const readiness=fails?'Boundary conflict':unresolvedBoundary||assumptions||unresolved?'Still investigating':!complete?'Incomplete assessment':'No unresolved blocker recorded';
 const evidence=assessed.length?(assessed.every(f=>f.evidence===3)?'Verified facts':assessed.every(f=>f.evidence===1)?'Assumptions':'Mixed facts, estimates and assumptions'):'Not assessed';
 const stressComplete=stressRows.every(r=>data.options.every(o=>data.stressTest.ratings[r.id]?.[o.id]));
 const stressValues=stressRows.flatMap(r=>data.options.map(o=>data.stressTest.ratings[r.id]?.[o.id]));
 const robust=!stressComplete?'Not assessed':stressValues.includes('too-much')?'Important pressure points':stressValues.includes('limit')||assumptions?'Limited room for setbacks':'Manageable in tested conditions';
 return {scores,lean,readiness,evidence,robust,top,gap,complete,unresolved};
}
function boundaryInvestigations(){if(data.hasHardBoundaries!=="yes")return[];const out=[];data.rules.forEach(r=>data.options.forEach(o=>{if(r.status&&r.status[o.id]==="unknown"){const q=(r.investigate&&r.investigate[o.id])||"";if(q)out.push(q)}}));return out}
function tradeoffInvestigations(){const out=[];data.options.forEach(o=>{if(o.trade?.foregoneState==="unknown"&&o.trade.foregoneUnknown)out.push(o.trade.foregoneUnknown);if(o.trade?.commitmentState==="unknown"&&o.trade.commitmentUnknown)out.push(o.trade.commitmentUnknown)});return out}
function allInvestigations(){return [...new Set([...boundaryInvestigations(),...tradeoffInvestigations(),...(data.investigate||[]).filter(Boolean)].map(x=>x.trim()).filter(Boolean))]}
function judgmentSignals(){const rows=[...judgmentCore,...judgmentConditionalRows()];return rows.filter(r=>["maybe","yes"].includes(data.judgment.answers[r.id]))}
function vulnerabilityItems(){
const out=(data.inversion||[]).filter(Boolean).map(x=>x.trim()).filter(Boolean);
if(data.stressTest.leastRoom)out.push(data.stressTest.leastRoom.trim());
stressRows.forEach(r=>{
  const too=data.options.filter(o=>data.stressTest.ratings?.[r.id]?.[o.id]==="too-much").map(o=>o.name);
  const limit=data.options.filter(o=>data.stressTest.ratings?.[r.id]?.[o.id]==="limit").map(o=>o.name);
  if(too.length)out.push(r.label+": "+too.join(", ")+" could become unworkable or unacceptable.");
  else if(limit.length)out.push(r.label+": "+limit.join(", ")+" would be at the limit.");
});
return [...new Set(out.filter(Boolean))]
}
function overviewList(items,empty="Nothing added yet."){return items.length?'<ul class="overview-list">'+items.map(x=>'<li>'+esc(x)+'</li>').join("")+'</ul>':'<p class="muted">'+esc(empty)+'</p>'}
function decisionOverview(){
 const a=analyse();const edit=i=>'<button class="edit-link" data-edit="'+i+'">Edit</button>';
 const section=(title,body,i)=>'<section class="overview-section"><div class="section-heading"><h3>'+title+'</h3>'+edit(i)+'</div>'+body+'</section>';
 const priorities=data.priorities.map(id=>lifeDomains.find(d=>d.id===id)?.title).filter(Boolean);
 const drivers=[...data.factors].sort((x,y)=>(y.importance||0)-(x.importance||0));
 const driverRows=drivers.length?drivers.map(f=>'<details class="overview-driver"><summary><span><strong>'+esc(f.name||'Untitled driver')+'</strong><small>'+(['Not assessed','Low','Medium','High'][f.importance||0])+' importance · '+(['Not assessed','Assumption','Reasonable estimate','Verified fact'][f.evidence||0])+'</small></span><span class="badge">'+esc(driverDirection(f))+'</span></summary><p>'+esc(f.rationale||'No reasoning added yet.')+'</p>'+((f.sources||[]).length?'<ul>'+f.sources.map(r=>'<li>'+esc(r.text)+'</li>').join('')+'</ul>':'')+'</details>').join(''):'<p class="muted">Decision drivers have not been assessed yet.</p>';
 const rules=data.hasHardBoundaries==='yes'?data.rules:[];
 const boundaryList=rules.length?'<h4>Hard boundaries</h4>'+rules.map(r=>'<div class="boundary-summary"><strong>'+esc(r.text||'Boundary not defined')+'</strong><p>'+data.options.map(o=>esc(o.name)+': '+({'yes':'Within boundary','no':'Crosses boundary','unknown':'Needs checking'}[r.status[o.id]]||'Not assessed')).join(' · ')+'</p></div>').join(''):'';
 const signals=judgmentSignals();const judgmentAnswered=[...judgmentCore,...judgmentConditionalRows()].every(r=>data.judgment.answers[r.id]);
 const reverse=data.options.map(o=>'<div class="overview-reverse"><strong>'+esc(o.name)+'</strong><p>'+(['Not assessed','Easy to change course','Moderately difficult to change course','Difficult to change course'][o.reverse.difficulty||0])+'</p>'+((o.reverse.costs||[]).length?'<small>Potential costs: '+esc(o.reverse.costs.join(', '))+'</small>':'')+(o.reverse.easier?'<p>'+esc(o.reverse.easier)+'</p>':'')+'</div>').join('');
 return '<div class="decision-overview">'+decisionAnchor()+'<div class="overview-hero"><span class="assessment-label">'+(a.complete?'Reviewed assessment':'Partial assessment')+'</span><h2>'+esc(a.lean==='Not assessed'?'Your decision is still taking shape':a.lean==='No clear lean'?'Your reasons do not point clearly to one path':'Your reasons currently show a '+a.lean.toLowerCase())+'</h2><p>'+esc(a.unresolved?a.unresolved+' question'+(a.unresolved===1?' remains':'s remain')+' unresolved.':a.complete?'No unresolved information gaps have been recorded.':'Complete the relevant checks before interpreting this as a full assessment.')+'</p><div class="overview-state"><div><span>Evidence</span><strong>'+esc(a.evidence)+'</strong></div><div><span>Readiness</span><strong>'+esc(a.readiness)+'</strong></div><div><span>Stability</span><strong>'+esc(a.robust)+'</strong></div></div><small>Based on your entries. This is an orientation, not a recommendation.</small></div>'+section('What you want to achieve','<p class="overview-objective">'+esc(data.objective||'Not answered yet.')+'</p>',0)+section('What this decision needs to protect',overviewList(priorities,'Not assessed yet.')+boundaryList,1)+section('What is driving your view',driverRows,10)+'<div class="overview-pair">'+section('What you still need to find out',overviewList(allInvestigations(),'No information gaps recorded yet.'),2)+section('Where the decision is vulnerable',overviewList(vulnerabilityItems(),'No pressure points recorded yet.'),7)+section('Worth noticing',signals.length?overviewList(signals.map(r=>r.summary+(data.judgment.answers[r.id]==='yes'?' — your view changes.':' — you are unsure whether this affects your view.')),''):'<p class="muted">'+(judgmentAnswered?'No influences flagged in the checks answered.':'Judgment Check is not fully assessed yet.')+'</p>',8)+section('Room to change course',reverse,9)+'</div><section class="ai-export"><h3>Use this decision with AI</h3><p>Here’s your decision in structured context, ready to paste into ChatGPT or any other GenAI model for deeper analysis.</p><div class="chips"><button id="copyContext">Copy decision context</button><button id="downloadContext" class="secondary">Download .md</button><span id="copyFeedback" role="status" aria-live="polite"></span></div><details><summary>Preview structured context</summary><pre class="brief">'+esc(decisionContextText())+'</pre></details></section></div>';
}
function decisionContextText(){const a=analyse(),out=[];const add=x=>out.push(x);add("# Clarity Decision Context");add("\nAssessment: "+(a.complete?"Reviewed":"Partial / incomplete"));add("\n## Decision\n"+(data.decision||"[Not answered]"));add("\n## Options\n"+data.options.map((o,i)=>String.fromCharCode(65+i)+". "+o.name).join("\n"));add("\n## Objective\n"+(data.objective||"[Not answered]"));const initialInclination=data.inclination==="none"?"No clear inclination yet":(data.options.find(o=>o.id===data.inclination)?.name||"[Not answered]");add("\n## Starting inclination\n"+initialInclination);add("\n## Time horizon\n"+(data.horizon||"[Not answered]"));add("\n## What matters most in this decision\n"+fmt(data.priorities.map(id=>lifeDomains.find(d=>d.id===id)?.title).filter(Boolean)));add("\n## Hard boundaries");if(data.hasHardBoundaries!=="yes"){add("\n"+(data.hasHardBoundaries==="no"?"No hard boundaries stated.":"[Not assessed]"))}else{data.rules.forEach(r=>add("\n- "+(r.text||"[Untitled boundary]")+"\n"+data.options.map(o=>{const s=(r.status&&r.status[o.id])||"[Not answered]";const q=s==="unknown"&&r.investigate&&r.investigate[o.id]?" — need to find out: "+r.investigate[o.id]:"";return "  - "+o.name+": "+s+q}).join("\n")))}add("\n## Compounding\nWhat I want this decision to grow:\n"+(data.compounding.grow.length?data.compounding.grow.map(id=>{const x=compoundGrow.find(v=>v.id===id);const detail=data.compounding.growDetails[id]||"[Not specified]";const opts=(data.compounding.growOptions[id]||[]).map(oid=>data.options.find(o=>o.id===oid)?.name).filter(Boolean);return "- "+(x?.title||id)+": "+detail+" | paths that build it: "+(opts.length?opts.join(", "):"[None selected]")}).join("\n"):"[None selected]")+"\nWhat I do not want this decision to compound:\n"+(data.compounding.avoid.length?data.compounding.avoid.map(id=>{const x=compoundAvoid.find(v=>v.id===id);const detail=data.compounding.avoidDetails[id]||"[Not specified]";const opts=(data.compounding.avoidOptions[id]||[]).map(oid=>data.options.find(o=>o.id===oid)?.name).filter(Boolean);return "- "+(x?.title||id)+": "+detail+" | paths most likely to compound it: "+(opts.length?opts.join(", "):"[None selected]")}).join("\n"):"[None selected]"));data.options.forEach(o=>{add("\n## "+o.name+" — Trade-offs\nWhat this path closes off:\n"+(o.trade.foregoneState==="none"?"[No meaningful sacrifice identified yet]":o.trade.foregoneState==="unknown"?"[Not enough information yet]"+(o.trade.foregoneUnknown?" — Need to find out: "+o.trade.foregoneUnknown:""):fmt(o.trade.foregone))+"\nWhat this path requires or ties up:\n"+(o.trade.commitmentState==="none"?"[No meaningful cost identified yet]":o.trade.commitmentState==="unknown"?"[Not enough information yet]"+(o.trade.commitmentUnknown?" — Need to find out: "+o.trade.commitmentUnknown:""):fmt(o.trade.commitments)));add("\n## "+o.name+" — Incentives\nWhat this path promises:\n"+fmt((o.incentives.promises||[]).map(id=>incentivePromises.find(x=>x.id===id)?.title).filter(Boolean))+"\nWhat this path helps avoid:\n"+fmt((o.incentives.avoid||[]).map(id=>incentiveAvoid.find(x=>x.id===id)?.title).filter(Boolean)));add("\n## "+o.name+" — Chain Effects\nPlausible upside chain: "+chain((o.consequence.positive||[]).slice(0,3))+"\nPlausible downside chain: "+chain((o.consequence.negative||[]).slice(0,3)));add("\n## "+o.name+" — Reversibility\nDifficulty: "+["Not assessed","Easy","Moderate","Difficult"][o.reverse.difficulty||0]+"\nCosts:\n"+fmt(o.reverse.costs)+"\nMake it easier to reverse:\n"+(o.reverse.easier||"[Not answered]"))});add("\n## Inversion\nWhat would make this decision fail to achieve the intended outcome?\n"+fmt(data.inversion));add("\n## Stress Test\n"+stressRows.map(r=>{const cells=data.options.map(o=>{const v=(data.stressTest.ratings[r.id]&&data.stressTest.ratings[r.id][o.id])||"";const label=stressChoices.find(c=>c.value===v)?.label||"[Not answered]";return o.name+": "+label}).join(" | ");return "- "+r.label+" — "+cells}).join("\n")+"\nLeast room for things going wrong:\n"+(data.stressTest.leastRoom||"[Not answered]"));add("\n## Incentives I do not want to keep reinforcing\n"+(data.incentiveConcernNone?"[None selected]":fmt(data.incentiveConcerns.map(id=>[...incentivePromises,...incentiveAvoid].find(x=>x.id===id)?.title).filter(Boolean))));add("\n## Judgment Check\n"+[...judgmentCore,...judgmentConditionalRows()].map(r=>"- "+r.question+" — "+({no:"No — I would see it the same way",maybe:"Maybe — I’m not sure",yes:"Yes — I would see it differently"}[data.judgment.answers[r.id]]||"[Not answered]")).join("\n")+"\nStrongest serious case that my current view could be wrong:\n"+(data.judgment.strongestCase||"[Not answered]")+"\nEvidence that would most seriously change my view:\n"+(data.judgment.changeEvidence||"[Not answered]"));add("\n## Decision drivers\n"+(data.factors.length?data.factors.map(f=>"- "+(f.name||"[Untitled]")+" | "+driverDirection(f)+" | importance "+["","low","medium","high"][f.importance]+" | evidence "+["","assumption","reasonable estimate","verified fact"][f.evidence]+"\n  "+(f.rationale||"")).join("\n"):"[None added]"));add("\n## Current decision state\nCurrent position: "+a.lean+"\nReadiness: "+a.readiness+"\nEvidence quality: "+a.evidence+"\nStability: "+a.robust);add("\n## What I still need to find out\n"+fmt(allInvestigations()));add("\n---\n# INSTRUCTION FOR FURTHER ANALYSIS\nAnalyze this decision critically without making the decision for me. Do not simply reinforce my current preference. Identify missing considerations and blind spots; challenge weak assumptions; separate facts, estimates and assumptions; identify double-counting; examine psychological pressures; trace second- and third-order consequences; identify the unknowns with the highest value of information; tell me what evidence I should gather next; argue the strongest serious case for each major option; and point out what evidence would rationally change the current lean. Do not reduce the decision to one score or tell me what to choose.");return out.join("\n")}
const fmt=a=>(a||[]).filter(Boolean).length?(a||[]).filter(Boolean).map(x=>"- "+x).join("\n"):"[None added]";
const chain=a=>(a||[]).filter(Boolean).join(" → ")||"[Not answered]";
function bind(){document.querySelectorAll("[data-step]").forEach(b=>b.onclick=()=>{const nextStep=+b.dataset.step;if((nextStep===2||nextStep===3||nextStep===5)&&step!==nextStep)active=data.options[0].id;if(nextStep===3&&step!==3)incentiveReview=false;step=nextStep;render()});document.querySelectorAll("[data-tab]").forEach(b=>b.onclick=()=>{active=b.dataset.tab;render()});document.querySelectorAll("[data-root]").forEach(e=>e.oninput=()=>{data[e.dataset.root]=e.value;save()});document.querySelectorAll("[data-optname]").forEach(e=>e.oninput=()=>setOptName(e.dataset.optname,e.value));document.querySelectorAll("[data-inclination]").forEach(e=>e.onchange=()=>{data.inclination=e.value;save()});document.querySelectorAll("[data-horizon]").forEach(e=>e.onchange=()=>{data.horizon=e.value;save()});document.querySelectorAll("[data-removeopt]").forEach(b=>b.onclick=()=>{if(data.options.length<=2)return;data.options=data.options.filter(o=>o.id!==b.dataset.removeopt);if(active===b.dataset.removeopt)active=data.options[0].id;if(data.inclination===b.dataset.removeopt)data.inclination="";render()});if($("#addOpt"))$("#addOpt").onclick=()=>{if(data.options.length<5){const o=blankOption("Option "+String.fromCharCode(65+data.options.length));data.options.push(o);active=o.id;render()}};document.querySelectorAll("[data-priority]").forEach(e=>e.onchange=()=>{if(e.checked&&data.priorities.length<3)data.priorities.push(e.value);if(!e.checked)data.priorities=data.priorities.filter(x=>x!==e.value);render()});document.querySelectorAll("[data-hardboundaries]").forEach(e=>e.onchange=()=>{data.hasHardBoundaries=e.value;if(e.value==="yes"&&!data.rules.length)data.rules.push({id:uid(),text:"",status:{},investigate:{}});render()});if($("#addRule"))$("#addRule").onclick=()=>{data.rules.push({id:uid(),text:"",status:{},investigate:{}});render()};document.querySelectorAll("[data-rule]").forEach(e=>e.oninput=()=>{data.rules.find(r=>r.id===e.dataset.rule).text=e.value;save()});document.querySelectorAll("[data-rulestatus]").forEach(e=>e.onchange=()=>{const r=data.rules.find(r=>r.id===e.dataset.rulestatus);r.status[e.dataset.oid]=e.value;if(e.value!=="unknown"&&r.investigate)delete r.investigate[e.dataset.oid];render()});document.querySelectorAll("[data-ruleinvestigate]").forEach(e=>e.oninput=()=>{const r=data.rules.find(r=>r.id===e.dataset.ruleinvestigate);r.investigate[e.dataset.oid]=e.value;save()});document.querySelectorAll("[data-delrule]").forEach(b=>b.onclick=()=>{data.rules=data.rules.filter(r=>r.id!==b.dataset.delrule);render()});document.querySelectorAll("[data-list]").forEach(e=>e.oninput=()=>{const a=[...getPath(e.dataset.list)];a[+e.dataset.i]=e.value;setPath(e.dataset.list,a);if(e.dataset.list.includes(".trade.foregone")&&e.value.trim())option().trade.foregoneState="";if(e.dataset.list.includes(".trade.commitments")&&e.value.trim())option().trade.commitmentState="";save()});document.querySelectorAll("[data-del]").forEach(b=>b.onclick=()=>{const a=[...getPath(b.dataset.del)];a.splice(+b.dataset.i,1);setPath(b.dataset.del,a);render()});document.querySelectorAll("[data-add]").forEach(b=>b.onclick=()=>{setPath(b.dataset.add,[...getPath(b.dataset.add),""]);render()});document.querySelectorAll("[data-tradestate]").forEach(e=>e.onchange=()=>{const t=option().trade,k=e.dataset.tradestate;t[k+"State"]=e.value;if(e.value!=="unknown")t[k+"Unknown"]="";render()});document.querySelectorAll("[data-tradeunknown]").forEach(e=>e.oninput=()=>{option().trade[e.dataset.tradeunknown+"Unknown"]=e.value;save()});document.querySelectorAll("[data-tradeprev]").forEach(b=>b.onclick=()=>{const i=Math.max(0,data.options.indexOf(option())-1);active=data.options[i].id;render()});document.querySelectorAll("[data-tradenext]").forEach(b=>b.onclick=()=>{const i=Math.min(data.options.length-1,data.options.indexOf(option())+1);active=data.options[i].id;render()});document.querySelectorAll("[data-incentive]").forEach(e=>e.onchange=()=>{const a=option().incentives[e.dataset.incentive]||[];option().incentives[e.dataset.incentive]=e.checked?[...new Set([...a,e.value])]:a.filter(x=>x!==e.value);render()});document.querySelectorAll("[data-incentiveprev]").forEach(b=>b.onclick=()=>{const i=Math.max(0,data.options.indexOf(option())-1);active=data.options[i].id;render()});document.querySelectorAll("[data-incentivenext]").forEach(b=>b.onclick=()=>{const i=Math.min(data.options.length-1,data.options.indexOf(option())+1);active=data.options[i].id;render()});document.querySelectorAll("[data-incentivereview]").forEach(b=>b.onclick=()=>{incentiveReview=true;render()});document.querySelectorAll("[data-incentiveback]").forEach(b=>b.onclick=()=>{incentiveReview=false;active=data.options[data.options.length-1].id;render()});document.querySelectorAll("[data-incentiveconcern]").forEach(e=>e.onchange=()=>{data.incentiveConcernNone=false;data.incentiveConcerns=e.checked?[...new Set([...data.incentiveConcerns,e.value])]:data.incentiveConcerns.filter(x=>x!==e.value);render()});document.querySelectorAll("[data-incentivenone]").forEach(e=>e.onchange=()=>{data.incentiveConcernNone=e.checked;if(e.checked)data.incentiveConcerns=[];render()});document.querySelectorAll("[data-compoundselect]").forEach(e=>e.onchange=()=>{const k=e.dataset.compoundselect,a=data.compounding[k];if(e.checked&&a.length<3)a.push(e.value);if(!e.checked){data.compounding[k]=a.filter(x=>x!==e.value);delete data.compounding[k+"Details"][e.value];delete data.compounding[k+"Options"][e.value]}render()});document.querySelectorAll("[data-compounddetail]").forEach(e=>e.oninput=()=>{data.compounding[e.dataset.compounddetail+"Details"][e.dataset.compoundid]=e.value;save()});document.querySelectorAll("[data-compoundoption]").forEach(e=>e.onchange=()=>{const k=e.dataset.compoundoption+"Options",id=e.dataset.compoundid,a=data.compounding[k][id]||[];data.compounding[k][id]=e.checked?[...new Set([...a,e.value])]:a.filter(x=>x!==e.value);save()});document.querySelectorAll("[data-optfield]").forEach(e=>e.oninput=()=>{const [a,b]=e.dataset.optfield.split(".");option()[a][b]=e.value;save()});document.querySelectorAll("[data-chain]").forEach(e=>e.oninput=()=>{option().consequence[e.dataset.chain][+e.dataset.i]=e.value;save()});document.querySelectorAll("[data-chainexpand]").forEach(b=>b.onclick=()=>{if(!option().consequence.expanded)option().consequence.expanded={positive:false,negative:false};option().consequence.expanded[b.dataset.chainexpand]=true;render()});document.querySelectorAll("[data-chainprev]").forEach(b=>b.onclick=()=>{const i=Math.max(0,data.options.indexOf(option())-1);active=data.options[i].id;render()});document.querySelectorAll("[data-chainnext]").forEach(b=>b.onclick=()=>{const i=Math.min(data.options.length-1,data.options.indexOf(option())+1);active=data.options[i].id;render()});document.querySelectorAll("[data-chaincontinue]").forEach(b=>b.onclick=()=>{active=data.options[0].id;step=6;render()});document.querySelectorAll("[data-stressrow]").forEach(e=>e.onchange=()=>{const r=e.dataset.stressrow,o=e.dataset.stressoption;if(!data.stressTest.ratings[r])data.stressTest.ratings[r]={};data.stressTest.ratings[r][o]=e.value;save()});document.querySelectorAll("[data-stresssummary]").forEach(e=>e.oninput=()=>{data.stressTest.leastRoom=e.value;save()});document.querySelectorAll("[data-judgment]").forEach(e=>e.onchange=()=>{data.judgment.answers[e.dataset.judgment]=e.value;save()});document.querySelectorAll("[data-judgmenttext]").forEach(e=>e.oninput=()=>{data.judgment[e.dataset.judgmenttext]=e.value;save()});document.querySelectorAll("[data-difficulty]").forEach(e=>e.onchange=()=>{option().reverse.difficulty=+e.value;save()});document.querySelectorAll("[data-revcost]").forEach(b=>b.onclick=()=>toggle(option().reverse.costs,b.dataset.revcost));if($("#addFactor"))$("#addFactor").onclick=()=>{data.factors.push({id:uid(),name:"",option:data.options[0].id,strength:1,importance:2,evidence:2,rationale:""});render()};document.querySelectorAll("[data-factor]").forEach(e=>{const h=()=>{const f=data.factors.find(x=>x.id===e.dataset.factor),k=e.dataset.key;f[k]=["strength","importance","evidence"].includes(k)?+e.value:e.value;save()};e.oninput=h;e.onchange=h});document.querySelectorAll("[data-delfactor]").forEach(b=>b.onclick=()=>{data.factors=data.factors.filter(x=>x.id!==b.dataset.delfactor);render()});if($("#copyContext"))$("#copyContext").onclick=()=>navigator.clipboard.writeText(decisionContextText());if($("#downloadContext"))$("#downloadContext").onclick=()=>{const blob=new Blob([decisionContextText()],{type:"text/markdown"}),u=URL.createObjectURL(blob),a=document.createElement("a");a.href=u;a.download="clarity-decision-context.md";a.click();URL.revokeObjectURL(u)}}
function toggle(arr,x){const i=arr.indexOf(x);i>=0?arr.splice(i,1):arr.push(x);render()}
$("#back").onclick=()=>{if(step===2||step===9){const i=data.options.indexOf(option());if(i>0){active=data.options[i-1].id;render();return}}if(step===3){if(incentiveReview){incentiveReview=false;active=data.options[data.options.length-1].id;render();return}const i=data.options.indexOf(option());if(i>0){active=data.options[i-1].id;render();return}}if(step===4){step=3;incentiveReview=true;active=data.options[data.options.length-1].id;render();return}if(step===5){const i=data.options.indexOf(option());if(i>0){active=data.options[i-1].id;render();return}}if(step===6){step=5;active=data.options[data.options.length-1].id;render();return}if(step===7){step=6;render();return}step=Math.max(0,step-1);render()};$("#next").onclick=()=>{if(step===1||step===8)active=data.options[0].id;if(step===2||step===9){const i=data.options.indexOf(option());if(i<data.options.length-1){active=data.options[i+1].id;render();return}active=data.options[0].id;incentiveReview=false}if(step===3){if(!incentiveReview){const i=data.options.indexOf(option());if(i<data.options.length-1){active=data.options[i+1].id;render();return}incentiveReview=true;render();return}incentiveReview=false;active=data.options[0].id}if(step===4)active=data.options[0].id;if(step===5){const i=data.options.indexOf(option());if(i<data.options.length-1){active=data.options[i+1].id;render();return}active=data.options[0].id}step=Math.min(steps.length-1,step+1);render()};$("#reset").onclick=()=>{if(confirm("Start a new decision?")){data=fresh();active=data.options[0].id;incentiveReview=false;step=0;render()}};
